import Foundation
public enum AutomationToolSchemas {
    public static func tools(shop:JSONValue,text:JSONValue)->[JSONValue] {
        func tool(_ name:String,_ description:String,_ properties:[String:JSONValue],_ required:[String],read:Bool=false)->JSONValue{.object(["name":.string(name),"description":.string(description),"inputSchema":.object(["type":.string("object"),"properties":.object(properties),"required":.array(required.map(JSONValue.string)),"additionalProperties":.bool(false)]),"annotations":.object(["readOnlyHint":.bool(read),"destructiveHint":.bool(false),"idempotentHint":.bool(read),"openWorldHint":.bool(true)])])}
        let boolean:JSONValue = .object(["type":.string("boolean")])
        let section:JSONValue = .object(["type":.string("object"),"properties":.object(["type":.object(["type":.string("string"),"enum":.array([.string("text"),.string("image"),.string("product_slider")])]),"text":text,"file_index":.object(["type":.string("integer"),"minimum":.number(0)]),"product_ids":.object(["type":.string("array"),"items":text,"maxItems":.number(30)]),"title":text]),"required":.array([.string("type")]),"additionalProperties":.bool(false)])
        return [
            tool("propose_media_upload","Prepare a real local PNG/JPEG/WebP/GIF image for approval. Absolute local file path, ≤20 MB. Copies and hashes the file privately. After approval uploads binary data, verifies stored file size and returns media ID, filename and preview URL via list_operations. No remote mutation before approval.",["shop_id":shop,"file_path":text,"reason":text],["shop_id","file_path","reason"]),
            tool("propose_plugin_install","Prepare one local Shopware plugin ZIP ≤100 MB. Checks package paths, symlinks, expansion limits and composer metadata. Review shows required Shopware version. Approval uploads, refreshes, installs and optionally activates through official extension actions, then verifies plugin status. Shopware performs dependency validation. Existing installed plugins are not updated by this operation.",["shop_id":shop,"file_path":text,"activate":boolean,"reason":text],["shop_id","file_path","reason"]),
            tool("propose_campaign","Prepare one coherent CMS campaign with text, local images and existing product sliders. Files are staged locally and shown with the sections in Shopdeck. Approval uploads media, creates and reads back CMS slots and landing page. publish defaults false (draft). Explicit publish=true creates an active landing page and checks storefront reachability. list_operations returns saved IDs, admin URL, media URLs and separately verified reachable storefront URLs. This does not execute an older generic CMS proposal.",["shop_id":shop,"title":text,"sales_channel_id":text,"sections":.object(["type":.string("array"),"items":section,"minItems":.number(1),"maxItems":.number(20)]),"files":.object(["type":.string("array"),"items":text,"maxItems":.number(10)]),"publish":boolean,"reason":text],["shop_id","title","sales_channel_id","sections","reason"]),
            tool("list_operations","Read approval, execution checkpoints, errors and independently verified results for file, plugin, campaign and native MCP operations in one explicit shop.",["shop_id":shop],["shop_id"],read:true),
            tool("call_shopware_tool","Invoke a native tool from discover_shopware_tools. Session availability is distinct from the capability catalogue. Safe non-personal entity reads run directly; all mutations, configuration reads and toolset changes become local approval requests. A catalogue-only tool can be unavailable on the shop and will return an explicit error. Arguments follow the native tool's schema.",["shop_id":shop,"name":text,"arguments":.object(["type":.string("object")]),"reason":text],["shop_id","name","arguments"])
        ]
    }
}
